// LEARN(ts.objects-classes.modules): import type is erased before the code runs; imports without `type` are kept.

// This sandbox runs one file: ./billing.ts does not exist here. The program
// still runs, because a type-only import leaves no trace in the JavaScript.
import type { CURRENCIES, Invoice } from "./billing.ts";

// A value imported with `import type` still works in type positions...
type Currency = (typeof CURRENCIES)[number]; // "TRY" | "EUR" | "USD"
// ...but not at run time, where it doesn't exist:
// console.log(CURRENCIES.length);
// error TS1361: 'CURRENCIES' cannot be used as a value because it was imported using 'import type'.

const invoices: Invoice[] = [
  { id: "2026-001", total: 1250.5, currency: "TRY" },
  { id: "2026-002", total: 99, currency: "EUR" },
];

function format(amount: number, currency: Currency): string {
  return new Intl.NumberFormat("tr-TR", { style: "currency", currency }).format(amount);
}
for (const inv of invoices) console.log(inv.id, format(inv.total, inv.currency));

// Re-exports follow the same rule. `export { Invoice } from "./billing.ts"` gives
// error TS1205: Re-exporting a type when 'verbatimModuleSyntax' is enabled requires using 'export type'.
export type { Invoice } from "./billing.ts"; // erased as well

console.log("ran without loading ./billing.ts");

files.examples/02_live_bindings.ts:
// LEARN(ts.objects-classes.modules): ES modules export live bindings, run once per specifier, and expose read-only namespaces.

// A second module, inlined as a data: URL because this sandbox runs one file.
const source = `
  console.log("counter module evaluated");
  export let count = 0;
  export function increment() { count += 1; }
`;
const url = `data:text/javascript,${encodeURIComponent(source)}`;

// What a .d.ts file does: describe JavaScript the compiler can't see.
// import() of a computed string is typed Promise<any>, so this annotation
// is a promise you make, exactly like a hand-written declaration file.
interface CounterModule {
  readonly count: number;
  increment(): void;
}

const counter: CounterModule = await import(url);
const { count: snapshot } = counter; // destructuring copies today's value
counter.increment();
counter.increment();
console.log(`live: ${counter.count}, snapshot: ${snapshot}`);

// Same specifier, same instance: the module body does not run again.
const again: CounterModule = await import(url);
console.log(`same instance: ${again === counter}, count: ${again.count}`);

// Importers read bindings; only the exporting module can assign them.
try {
  (counter as { count: number }).count = 100;
} catch (e) {
  console.log(e instanceof TypeError ? "TypeError: namespace is read-only" : e);
}

files.examples/03_barrels.ts:
// LEARN(ts.objects-classes.modules): a barrel evaluates every module it re-exports, and export * hides name clashes.

const mod = (source: string) => `data:text/javascript,${encodeURIComponent(source)}`;

// Three feature modules, each announcing when its body runs.
const dates = mod(`
  console.log("evaluating dates");
  export const formatDate = (d) => d.toISOString().slice(0, 10);`);
const money = mod(`
  console.log("evaluating money");
  export const formatMoney = (n) => n.toLocaleString("tr-TR", { minimumFractionDigits: 2 });
  export const VERSION = "money 1.4";`);
const charts = mod(`
  console.log("evaluating charts (imagine 300 kB)");
  export const drawChart = () => "chart";
  export const VERSION = "charts 2.0";`);

// The barrel: an index.ts made of `export *` lines.
const barrel = mod(`
  export * from "${dates}";
  export * from "${money}";
  export * from "${charts}";`);

interface Shared {
  formatMoney(n: number): string;
  VERSION?: string;
}

// A direct import evaluates just that module.
const direct: Shared = await import(money);
console.log(direct.formatMoney(1250.5), direct.VERSION);

// Through the barrel, the same function costs every sibling module as well.
// money is cached and does not run again: one instance per specifier.
const shared: Shared = await import(barrel);
console.log(`same function: ${shared.formatMoney === direct.formatMoney}`);

// Two modules export VERSION, so export * exports neither: no error, no value.
console.log(`VERSION: ${shared.VERSION}; exports: ${Object.keys(shared).join(", ")}`);
